import copy


def merge_config(defaults, overrides) -> dict:
    """Merge defaults with overrides recursively.

    When a key occurs in both and both values are dictionaries, merge recursively.
    Otherwise, override replaces default completely.
    All values are deep-copied to avoid aliasing.
    """
    def deep_merge(base, override):
        # Start with empty dict, build up result
        result = {}

        for key, base_val in base.items():
            override_val = override.get(key)

            if key not in override:
                # Key only in defaults, deep copy base value
                result[key] = copy.deepcopy(base_val)
            elif isinstance(base_val, dict) and isinstance(override_val, dict):
                # Both are dicts, merge recursively
                result[key] = deep_merge(base_val, override_val)
            else:
                # Override replaces default completely (deep copy override value)
                result[key] = copy.deepcopy(override_val)

        # Now add keys only from overrides
        for key, override_val in override.items():
            if key not in base:
                # Key only in overrides, deep copy override value
                result[key] = copy.deepcopy(override_val)

        return result

    return deep_merge(defaults, overrides)
